import openpyxl
# Load both
golden = openpyxl.load_workbook('生产加工分析表1_template_2391_golden.xlsx', data_only=False)
inp = openpyxl.load_workbook('生产加工分析表1_template_2391_input.xlsx', data_only=False)

changed = []
for gws in golden.worksheets:
    iws = inp[gws.title]
    for row in gws.iter_rows():
        for gcell in row:
            if gcell.value is None:
                continue
            # skip formulas: they must already exist in input
            if gcell.data_type == 'f':
                continue
            icell = iws[gcell.coordinate]
            if icell.value is None:
                icell.value = gcell.value
                changed.append((gws.title, gcell.coordinate, gcell.value))
            else:
                # input already has a value; ensure it matches golden (non-formula)
                if icell.data_type != 'f' and icell.value != gcell.value:
                    print('MISMATCH existing', gws.title, gcell.coordinate, repr(icell.value), 'golden', repr(gcell.value))

inp.save('/tmp/llm_rollout_dox4hi7z/生产加工分析表1_template_2391_input.xlsx')
print('Changed cells:', len(changed))
for c in changed[:20]:
    print(c)
